import config from './site.config.json' with { type: 'json' };
const $ = (id) => document.getElementById(id);
const selector = (q, scope=document) => Array.from(scope.querySelectorAll(q));
const demoData = {
 cafe: {name:'Neighborhood café', aov:23.8, costRate:.56, orders:2575, trend:[81,94,88,111,117,105,133,143,138,158,172,186],insight:'Sales have grown across the sample year. Before increasing discounts, compare the likely uplift in volume with the lower profit on each order.'},
 retail: {name:'Independent store',aov:62.4,costRate:.64,orders:1650,trend:[92,101,98,116,122,135,129,152,149,178,188,203],insight:'Revenue rises in the last quarter of the simulated year. A more detailed category and seasonality view would help separate sustained demand from temporary peaks.'},
 service:{name:'Local service business',aov:145,costRate:.39,orders:680,trend:[120,117,139,136,164,153,172,181,166,195,208,226],insight:'The strongest simulated months are near the end of the period. Track repeat requests and scheduling capacity before scaling promotions.'}
};
const monthNames=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const money=(v)=>'$'+Math.round(v).toLocaleString('en-US');
const number=(v)=>Math.round(v).toLocaleString('en-US');
const esc=(v)=>String(v).replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
let panelBefore=null, currentPanel=null, toastTimer, studio=null, currentFocusView='entrance';
function toast(message){const t=$('toast');t.textContent=message;t.classList.add('is-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('is-visible'),3200);}
function current(){return demoData[$('businessSelect').value]}
function dashboard(){
 const d=current(), n=Number($('periodSelect').value), weights=d.trend.slice(-n), totalWeight=d.trend.reduce((a,b)=>a+b,0), annual=d.aov*d.orders;
 const revenue=annual*weights.reduce((a,b)=>a+b,0)/totalWeight, orders=revenue/d.aov, margin=1-d.costRate;
 $('kpiRevenue').textContent=money(revenue);$('kpiOrders').textContent=number(orders);$('kpiMargin').textContent=(margin*100).toFixed(1)+'%';
 $('chartPeriod').textContent=n+' months';$('revenueChange').textContent=`${d.name} · synthetic`;$('dashInsight').textContent=d.insight;
 const top=Math.max(...weights)*1.17, pts=weights.map((v,i)=>[36+i*(597/Math.max(1,n-1)),193-(v/top)*156]);
 const path=pts.map((p,i)=>(i?'L':'M')+p.map(x=>x.toFixed(2)).join(' ')).join(' ');
 $('chartLine').setAttribute('d',path);$('chartArea').setAttribute('d',path+` L${pts[pts.length-1][0]} 200 L36 200 Z`);
 $('grid').innerHTML=[34,84,134,193].map(y=>`<line x1="36" y1="${y}" x2="633" y2="${y}" stroke="#adc0d9" stroke-opacity=".15" stroke-dasharray="3 7"/>`).join('');
 $('chartDots').innerHTML=pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#f1c990"><title>${monthNames[12-n+i]}: ${money(annual*weights[i]/totalWeight)}</title></circle>`).join('');
 $('monthLabels').innerHTML=pts.map((p,i)=>(n===12&&i%2===1?'':`<text x="${p[0]}" y="227" font-size="11" fill="#95a7bc" text-anchor="middle">${monthNames[12-n+i]}</text>`)).join('');
 simulation();
}
function simulation(){
 const d=current(),discount=Number($('discountInput').value)/100;
 const count=d.orders*(1+1.25*discount),unit=d.aov*(1-discount),cost=d.aov*d.costRate;
 const contribution=(unit-cost)*count,baseline=(d.aov-cost)*d.orders,diff=contribution-baseline;
 $('discountLabel').textContent=Math.round(discount*100)+'%';$('contribution').textContent=money(contribution);$('contributionDelta').textContent=(diff>=0?'+':'−')+money(Math.abs(diff));
 $('contributionDelta').classList.toggle('negative',diff<0);$('contributionDelta').classList.toggle('positive',diff>=0);
}
function panelHtml(id){
 if(id==='analytics')return `<div class="eyebrow">01 / LIVE INTERACTIVE LAB</div><h2>See the numbers.<br><em>Understand the why.</em></h2><p class="panel-lead">A working simulated business intelligence experience. Choose a fictional business, compare time windows, and adjust a discount to explore the trade-offs.</p><div class="panel-tags"><span>Decision support</span><span>Dynamic calculations</span><span>Everyday language</span></div><div class="panel-feature">The full dashboard is already live on this page. Open it to interact with all the metrics, charts and controls.</div><button class="panel-action" id="jumpToLab">Open live dashboard ↗</button><p class="panel-lead" style="margin-top:22px;font-size:11px">All numbers are fabricated for demonstration purposes.</p>`;
 if(id==='automation')return `<div class="eyebrow">02 / INTERACTIVE PROCESS</div><h2>A clearer way<br>to <em>get things done.</em></h2><p class="panel-lead">An independent workflow concept. See what happens when a customer enquiry arrives, gets organized, and receives a follow-up. Select each stage to explore it.</p><div class="step-list" id="stepList"><button data-step="0" class="selected"><span><strong>01 · Receive the enquiry</strong><small>Bring requests into one visible place.</small></span><span>✓</span></button><button data-step="1"><span><strong>02 · Check what's needed</strong><small>Identify missing details before responding.</small></span><span>→</span></button><button data-step="2"><span><strong>03 · Prepare the follow-up</strong><small>Make the next action clear and trackable.</small></span><span>→</span></button></div><div class="workflow-status" id="stepDetails">A fictional customer has sent a request. The workflow logs it with a status and an owner.</div><button class="panel-action" id="nextStep">Continue workflow →</button><p class="panel-lead" style="margin-top:24px;font-size:11px">This prototype does not process real messages or send emails.</p>`;
 if(id==='quality')return `<div class="eyebrow">03 / INTERACTIVE QUALITY REVIEW</div><h2>Better decisions<br>start with <em>better data.</em></h2><p class="panel-lead">Inspect a tiny fictional contact list. Flag missing information and duplicate records to see a simple data-quality review in action.</p><div id="records"><div class="record" data-issue="false"><span class="record-badge">PENDING</span><strong>Alex Rivera</strong><small>alex@example.test · ID 1042</small></div><div class="record" data-issue="true"><span class="record-badge">PENDING</span><strong>Jamie Chen</strong><small>No email · ID 1043</small></div><div class="record" data-issue="true"><span class="record-badge">PENDING</span><strong>Alex Rivera</strong><small>alex@example.test · ID 1042 · repeated record</small></div><div class="record" data-issue="false"><span class="record-badge">PENDING</span><strong>Sam Taylor</strong><small>sam@example.test · ID 1044</small></div></div><div class="quality-stats"><div><strong id="issueCount">0 / 2</strong><small>Issues found</small></div><div><strong id="reviewCount">0 / 4</strong><small>Records reviewed</small></div></div><button class="panel-action" id="resetRecords">Reset review</button><p class="panel-lead" style="margin-top:24px;font-size:11px">Every name and email is fictional. Click a row to mark it as correct or problematic.</p>`;
 if(id==='cv')return `<div class="eyebrow">03 / PROFESSIONAL PROFILE</div><h2>Eyad Beshier.<br><em>At a glance.</em></h2><p class="panel-lead">Business Informatics · Analytics · Practical digital solutions</p><div class="cv-grid"><div><h3>Experience</h3><p>Approximately one year of practical pricing-related and data-analysis experience. Employer details and internal examples are not included.</p></div><div><h3>Education</h3><p>Business Informatics studies bringing together business processes, information systems, and technology.</p></div><div><h3>Tools</h3><p>Excel, SQL queries, data visualization, SAP familiarity, prototyping, and workflow analysis.</p></div><div><h3>Approach</h3><p>Understand the business question, build a small proof of value, and make the result easy to maintain.</p></div></div><button class="panel-action" id="printResume">Print / Save this summary as PDF ↗</button><p class="panel-lead" style="margin-top:22px;font-size:11px">A public summary. Add verified dates, qualifications and contact information before using as a formal CV.</p>`;
 if(id==='experience')return `<div class="eyebrow">PROFESSIONAL JOURNEY</div><h2>Thoughtful analysis.<br><em>Practical outcomes.</em></h2><div class="timeline"><article><small>BUSINESS & DATA</small><h3>Pricing and analysis experience</h3><p>Experience working with structured business information, analytical checks, and reporting. Details relating to employers and confidential records are excluded.</p></article><article><small>TECHNOLOGY & PROTOTYPING</small><h3>Building useful tools</h3><p>Excel, SQL, systems thinking, process analysis, and prototypes designed around simple user needs.</p></article><article><small>ACADEMIC FOUNDATION</small><h3>Business Informatics</h3><p>Combining business concepts with digital systems to help solve everyday problems.</p></article></div><button class="panel-action" id="openCvFromExperience">Open profile ↗</button>`;
 if(id==='about')return `<div class="eyebrow">BEHIND THE WORK</div><h2>Curiosity with<br><em>a practical purpose.</em></h2><p class="panel-lead">I'm Eyad, a Business Informatics student interested in how business problems become better information, simpler routines and useful software. I enjoy the point where analytical thinking meets human-friendly design.</p><div class="panel-feature">“Technology matters most when the person using it feels more confident, not more confused.”</div><div class="timeline"><article><small>01 / LISTEN</small><h3>Find the real problem</h3><p>Start with everyday frustrations rather than technical jargon.</p></article><article><small>02 / MAKE IT VISIBLE</small><h3>Show the pattern</h3><p>Translate scattered data into something people can interpret.</p></article><article><small>03 / KEEP IT USEFUL</small><h3>Build the smallest helpful solution</h3><p>Prefer clarity and repeatability over unnecessary complexity.</p></article></div>`;
 if(id==='contact')return `<div class="eyebrow">START A CONVERSATION</div><h2>Something to<br><em>make simpler?</em></h2><p class="panel-lead">If you have a reporting challenge, repetitive workflow, or business question, I'd be interested in understanding it and exploring a practical first step.</p><div class="contact-option"><span><strong>GitHub</strong><small>Code, independent experiments and prototypes</small></span><a href="${esc(config.githubUrl)}" target="_blank" rel="noopener noreferrer">Visit profile ↗</a></div>${config.publicEmail?`<div class="contact-option"><span><strong>Email</strong><small>${esc(config.publicEmail)}</small></span><a href="mailto:${encodeURIComponent(config.publicEmail)}">Write an email ↗</a></div>`:'<div class="panel-feature">Public email has not been configured yet. Add it to <code>site.config.json</code> before your professional launch.</div>'}${config.linkedInUrl?`<div class="contact-option"><span><strong>LinkedIn</strong><small>Professional profile</small></span><a href="${esc(config.linkedInUrl)}" target="_blank" rel="noopener noreferrer">Connect ↗</a></div>`:''}`;
 return '';
}
function openPanel(id){
 if(!['analytics','automation','quality','cv','experience','about','contact'].includes(id))return;
 panelBefore=document.activeElement;currentPanel=id;
 $('panelEyebrow').textContent=`EYAD / ${id.toUpperCase()}`;$('panelBody').innerHTML=panelHtml(id);$('panelDialog').hidden=false;$('dialogShade').hidden=false;document.body.classList.add('modal-open');$('closePanel').focus();
 if(id==='analytics')$('jumpToLab').onclick=()=>{closePanel(); if(!$('studioOverlay').hidden)exitStudio();$('lab').scrollIntoView({behavior:'smooth'})};
 if(id==='automation')wireWorkflow();
 if(id==='quality')wireQuality();
 if(id==='cv')$('printResume').onclick=()=>window.print();
 if(id==='experience')$('openCvFromExperience').onclick=()=>openPanel('cv');
}
function closePanel(){$('panelDialog').hidden=true;$('dialogShade').hidden=true;document.body.classList.toggle('modal-open',!$('studioOverlay').hidden);currentPanel=null;panelBefore?.focus?.()}
let step=0;const stepMessages=[
 'A fictional customer has sent a request. The workflow logs it with a status and a responsible person.',
 'The request has been checked. The missing delivery date is now highlighted, so the next message is clear.',
 'A suggested follow-up is prepared. The item moves to a review queue instead of being forgotten.'
];
function wireWorkflow(){step=0;const buttons=selector('[data-step]', $('panelBody'));const select=(n)=>{step=n;buttons.forEach((b,i)=>b.classList.toggle('selected',i===n));$('stepDetails').textContent=stepMessages[n];$('nextStep').textContent=n===2?'Restart demonstration ↺':'Continue workflow →';};buttons.forEach((b,i)=>b.onclick=()=>select(i));$('nextStep').onclick=()=>select((step+1)%3);}
function wireQuality(){const records=selector('.record',$('records'));let status=new Array(records.length).fill(null);const render=()=>{records.forEach((r,i)=>{const badge=r.querySelector('.record-badge');badge.textContent=status[i]===null?'PENDING':status[i]?'ISSUE FOUND':'CLEAN';r.classList.toggle('clean',status[i]===false);});$('reviewCount').textContent=status.filter(x=>x!==null).length+' / 4';$('issueCount').textContent=status.filter((x,i)=>x===true&&records[i].dataset.issue==='true').length+' / 2'};records.forEach((r,i)=>{r.setAttribute('role','button');r.setAttribute('tabindex','0');r.setAttribute('aria-label','Review '+r.querySelector('strong').textContent);const action=()=>{status[i]=status[i]===null?true:status[i]===true?false:null;render()};r.onclick=action;r.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();action()}}});$('resetRecords').onclick=()=>{status.fill(null);render()};render()}
const studioDescription={entrance:['A room full of ideas.','Choose a viewpoint or click an object to explore.'],desk:['The analytics desk.','Select the monitor to open the sample dashboard.'],gallery:['The story wall.','Experience, CV, biography and contact are displayed here.'],lounge:['The conversation corner.','Explore the thinking behind the work.'],window:['The city at night.','Enjoy the panoramic studio view.']};
async function enterStudio(view='entrance'){
 currentFocusView=view;$('studioOverlay').hidden=false;document.body.classList.add('modal-open');$('studioCanvas').style.background=`center / cover url('./assets/studio-cinematic.webp')`;
 studioView(view);$('studioProgress').textContent='Loading original 3D room…';
 if(!studio){try{const module=await import('./scene.js');studio=await module.createStudio($('studioCanvas'),(panel)=>openPanel(panel));$('studioProgress').textContent='3D ROOM READY · CLICK TO EXPLORE';}catch(err){console.warn('3D could not load',err);$('studioProgress').textContent='3D UNAVAILABLE · PORTFOLIO CONTENT STILL ACCESSIBLE';studio={setView(){},destroy(){}};}}
 studio.setView(view);
}
function studioView(view){currentFocusView=view;const desc=studioDescription[view]??studioDescription.entrance;$('studioTitle').textContent=desc[0];$('studioDescription').textContent=desc[1];selector('[data-camera]').forEach(btn=>btn.classList.toggle('is-active',btn.dataset.camera===view));studio?.setView(view);}
function exitStudio(){$('studioOverlay').hidden=true;document.body.classList.toggle('modal-open',currentPanel!==null)}
function boot(){
 $('businessSelect').onchange=dashboard;$('periodSelect').onchange=dashboard;$('discountInput').oninput=simulation;dashboard();
 selector('[data-open]').forEach(btn=>btn.addEventListener('click',()=>openPanel(btn.dataset.open)));
 selector('[data-studio]').forEach(btn=>btn.addEventListener('click',()=>enterStudio(btn.dataset.studio)));
 selector('[data-camera]').forEach(btn=>btn.addEventListener('click',()=>{const view=btn.dataset.camera;studioView(view);if(!studio?.setView){toast('Portfolio views can be opened from the main page.')}else if($('studioProgress').textContent.startsWith('3D UNAVAILABLE')){if(view==='desk')openPanel('analytics');if(view==='gallery')openPanel('cv');if(view==='lounge')openPanel('about')}}));
 $('closePanel').onclick=closePanel;$('dialogShade').onclick=closePanel;$('exitStudio').onclick=exitStudio;
 window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(currentPanel)closePanel();else if(!$('studioOverlay').hidden)exitStudio();return}if(currentPanel&&e.key==='Tab'){const nodes=selector('a[href],button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex="0"]',$('panelDialog')).filter(x=>x.getClientRects().length);if(nodes.length){const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}});
 const observer=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){const nav=selector('.mobile-nav a');nav.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}})},{threshold:.35});['home','work','lab','about'].forEach(id=>observer.observe($(id)));
}
boot();
